package com.optilive.tracker
import android.os.Bundle
import android.webkit.WebView
import android.webkit.WebChromeClient
import android.webkit.GeolocationPermissions
import android.content.pm.PackageManager
import androidx.core.app.ActivityCompat
import android.widget.TextView
import androidx.appcompat.app.AppCompatActivity
class WeatherActivity:AppCompatActivity(){
 override fun onCreate(b:Bundle?){super.onCreate(b);setContentView(R.layout.activity_weather);findViewById<TextView>(R.id.back).setOnClickListener{finish()};val w=findViewById<WebView>(R.id.weatherWeb);w.settings.javaScriptEnabled=true;w.settings.domStorageEnabled=true;w.settings.setGeolocationEnabled(true);w.webChromeClient=object:WebChromeClient(){override fun onGeolocationPermissionsShowPrompt(origin:String?,callback:GeolocationPermissions.Callback?){if(ActivityCompat.checkSelfPermission(this@WeatherActivity,android.Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED)callback?.invoke(origin,true,false)else{ActivityCompat.requestPermissions(this@WeatherActivity,arrayOf(android.Manifest.permission.ACCESS_FINE_LOCATION,android.Manifest.permission.ACCESS_COARSE_LOCATION),701);callback?.invoke(origin,false,false)}}};w.loadDataWithBaseURL("https://api.open-meteo.com",html(),"text/html","UTF-8",null)}
 private fun html()="""<!doctype html><html><head><meta name='viewport' content='width=device-width,initial-scale=1'><style>
*{box-sizing:border-box}body{margin:0;padding:12px;background:#f2f6fa;font-family:Arial;color:#14263a}.card{background:#fff;border-radius:18px;padding:16px;margin-bottom:12px;box-shadow:0 4px 18px #17334d12}.title{font-size:13px;font-weight:800;color:#174d7d;letter-spacing:.3px}.muted{color:#758494;font-size:12px}.hero{background:linear-gradient(135deg,#fff 55%,#e9f5ff);position:relative;overflow:hidden}.wind{font-size:48px;font-weight:900;line-height:1;margin-top:14px}.wind small{font-size:20px}.dir{font-size:19px;font-weight:800;margin-top:5px}.arrow{position:absolute;right:22px;top:45px;width:70px;height:70px;border-radius:50%;background:#f2f8ff;display:flex;align-items:center;justify-content:center;font-size:42px;color:#087fe3}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:16px}.stat{background:#f5f8fb;border-radius:12px;padding:11px 5px;text-align:center;font-size:11px;color:#66788a}.stat b{display:block;font-size:16px;color:#16283a;margin-bottom:3px}.hours{display:flex;overflow-x:auto;gap:4px;padding-top:12px}.hour{min-width:72px;text-align:center;padding:10px 5px;border-right:1px solid #edf1f4}.hour.now{background:#edf6ff;border-radius:12px}.hour .arr{font-size:24px;color:#087fe3}.hour b{font-size:18px}.hour small{display:block;color:#728293;margin-top:5px}.tiles{display:grid;grid-template-columns:1fr 1fr;gap:8px}.tile{background:#fff;border-radius:16px;padding:13px;box-shadow:0 3px 14px #17334d10}.tile .v{font-size:19px;font-weight:900;margin-top:5px}.trend{color:#1aa260}.warn{color:#e07a00}.chart{height:135px;width:100%}.legend{font-size:11px;color:#718091;text-align:right}.wxrow{display:grid;grid-template-columns:65px repeat(6,1fr);font-size:11px;text-align:center;padding:7px 0;border-bottom:1px solid #edf1f4}.wxrow span:first-child{text-align:left;color:#60758a}.source{background:#eaf5ff;border-radius:12px;padding:10px;font-size:11px;color:#536c83}
</style></head><body>
<div class='card hero'><div class='title'>CONDICIONES ACTUALES</div><div id='src' class='muted'>Localizando campo de regatas…</div><div id='hero'></div></div>
<div class='card'><div class='title'>EVOLUCIÓN DEL VIENTO · PRÓXIMAS HORAS</div><div id='hours' class='hours'></div></div>
<div id='tiles' class='tiles'></div>
<div class='card' style='margin-top:12px'><div class='title'>VIENTO Y RACHAS</div><div class='legend'>● Viento &nbsp; ○ Rachas</div><canvas id='chart' class='chart'></canvas></div>
<div class='card'><div class='title'>OTROS DATOS METEOROLÓGICOS</div><div id='other'></div></div>
<div class='source'>ⓘ Fuente: Open-Meteo (modelo numérico). Los datos pueden diferir del viento medido sobre el agua.</div>
<script>
function dirs(d){return['N','NE','E','SE','S','SO','O','NO'][Math.round(d/45)%8]}
async function pos(){try{let b=await(await fetch('https://optilive-node-production.up.railway.app/api/boats')).json();if(b.length){let p=b.sort((a,b)=>(b.timestamp||0)-(a.timestamp||0))[0];return{lat:p.lat,lon:p.lon,src:'Campo de regatas · GPS flota'}}}catch(e){}return await new Promise((ok,no)=>navigator.geolocation.getCurrentPosition(x=>ok({lat:x.coords.latitude,lon:x.coords.longitude,src:'Ubicación de este móvil'}),no,{enableHighAccuracy:true,timeout:8000,maximumAge:60000}))}
function draw(v,g){let c=document.getElementById('chart'),d=devicePixelRatio||1,w=c.clientWidth,h=c.clientHeight;c.width=w*d;c.height=h*d;let x=c.getContext('2d');x.scale(d,d);let max=Math.max(25,...g)+2,p=16,dx=(w-p*2)/(v.length-1||1);x.lineWidth=1;x.strokeStyle='#dce6ef';for(let k=0;k<4;k++){let y=p+(h-2*p)*k/3;x.beginPath();x.moveTo(p,y);x.lineTo(w-p,y);x.stroke()}function line(a,col,lw){x.strokeStyle=col;x.lineWidth=lw;x.beginPath();a.forEach((n,i)=>{let xx=p+i*dx,yy=h-p-(n/max)*(h-2*p);i?x.lineTo(xx,yy):x.moveTo(xx,yy)});x.stroke()}line(g,'#65baf2',2);line(v,'#0871c9',3)}
async function go(){try{let p=await pos(),u='https://api.open-meteo.com/v1/forecast?latitude='+p.lat+'&longitude='+p.lon+'&current=temperature_2m,apparent_temperature,precipitation,cloud_cover,wind_speed_10m,wind_direction_10m,wind_gusts_10m&hourly=temperature_2m,precipitation_probability,cloud_cover,wind_speed_10m,wind_direction_10m,wind_gusts_10m&wind_speed_unit=kn&forecast_days=2',j=await(await fetch(u)).json(),c=j.current,H=j.hourly,start=Math.max(0,H.time.findIndex(x=>x>=c.time)),end=Math.min(start+8,H.time.length),v=H.wind_speed_10m.slice(start,end),g=H.wind_gusts_10m.slice(start,end),di=H.wind_direction_10m.slice(start,end),rain=H.precipitation_probability.slice(start,end),tmp=H.temperature_2m.slice(start,end),cloud=H.cloud_cover.slice(start,end);document.getElementById('src').innerHTML='📍 '+p.src;document.getElementById('hero').innerHTML='<div class="wind">'+c.wind_speed_10m.toFixed(1)+' <small>kn</small></div><div class="dir">Viento del '+dirs(c.wind_direction_10m)+' ('+Math.round(c.wind_direction_10m)+'°)</div><div class="arrow" style="transform:rotate('+c.wind_direction_10m+'deg)">↑</div><div class="grid"><div class="stat"><b>'+c.wind_gusts_10m.toFixed(1)+' kn</b>💨 Racha</div><div class="stat"><b>'+c.temperature_2m.toFixed(1)+' °C</b>🌡 Temp.</div><div class="stat"><b>'+c.apparent_temperature.toFixed(1)+' °C</b>💧 Sensación</div></div>';let hs='';for(let i=start;i<end;i++){hs+='<div class="hour '+(i==start?'now':'')+'"><small>'+H.time[i].slice(11,16)+'</small><div class="arr" style="transform:rotate('+H.wind_direction_10m[i]+'deg)">↑</div><b>'+H.wind_speed_10m[i].toFixed(0)+'</b> kn<small>R '+H.wind_gusts_10m[i].toFixed(0)+' kn</small></div>'}document.getElementById('hours').innerHTML=hs;let trend=v.length>3?v[3]-v[0]:0,mx=Math.max(...g),mi=g.indexOf(mx),mr=Math.max(...rain);document.getElementById('tiles').innerHTML='<div class="tile"><div class="title">DIRECCIÓN</div><div class="v">'+dirs(c.wind_direction_10m)+' · '+Math.round(c.wind_direction_10m)+'°</div><div class="muted">Ahora</div></div><div class="tile"><div class="title">TENDENCIA</div><div class="v '+(trend>=0?'trend':'')+'">'+(trend>=0?'↗ +':'↘ ')+trend.toFixed(1)+' kn</div><div class="muted">en 3 horas</div></div><div class="tile"><div class="title">RACHA MÁX.</div><div class="v '+(mx>=20?'warn':'')+'">💨 '+mx.toFixed(0)+' kn</div><div class="muted">'+H.time[start+mi].slice(11,16)+'</div></div><div class="tile"><div class="title">PROB. LLUVIA</div><div class="v">🌧 '+mr+'%</div><div class="muted">próximas horas</div></div>';draw(v,g);let labels='<div class="wxrow"><span></span>'+H.time.slice(start,start+6).map(t=>'<b>'+t.slice(11,16)+'</b>').join('')+'</div>',r1='<div class="wxrow"><span>🌡 Temp.</span>'+tmp.slice(0,6).map(n=>'<span>'+n.toFixed(0)+'°</span>').join('')+'</div>',r2='<div class="wxrow"><span>☁ Nubes</span>'+cloud.slice(0,6).map(n=>'<span>'+n+'%</span>').join('')+'</div>',r3='<div class="wxrow"><span>💧 Lluvia</span>'+rain.slice(0,6).map(n=>'<span>'+n+'%</span>').join('')+'</div>';document.getElementById('other').innerHTML=labels+r1+r2+r3}catch(e){document.getElementById('hero').innerHTML='<b>No se pudo obtener la ubicación.</b><div class="muted">Activa la ubicación o inicia el seguimiento de un barco.</div>'}}go();setInterval(go,300000)
</script></body></html>"""
}